original_checker='"""Independent literal, every full 800-year path, and legal/capital production fixtures."""\nfrom pathlib import Path\nimport tempfile,subprocess,sys,shutil,hashlib,json,lzma,runpy,io,contextlib\nhere=Path(__file__).resolve().parent\n_FILES={\'verification/verify.py\': "import subprocess,sys,pathlib,json,hashlib,shutil\\nroot=pathlib.Path(__file__).resolve().parents[1]\\na=json.loads((root/\'model-output.json\').read_text()); b=json.loads((root/\'verification/independent-output.json\').read_text());out={}\\nfor name,literal in b.items():\\n prod=a[\'results\'][name];mx=0.\\n for x,y in zip(literal[\'rows\'],prod[\'rows\']):\\n  for key in y[\'state\']:mx=max(mx,abs(x[key]-y[\'state\'][key]))\\n assert mx<1e-7\\n assert abs(prod[\'pv_per_share\']-literal[\'pv_per_share\'])<1e-9\\n out[name]={\'pv_difference\':abs(prod[\'pv_per_share\']-literal[\'pv_per_share\']),\'maximum_state_difference\':mx,\'periods\':len(literal[\'rows\']),\'all_state_fields_compared\':list(prod[\'rows\'][0][\'state\'])}\\n(root/\'verification/independent-comparison.json\').write_text(json.dumps(out,indent=2))\\niso=root/\'verification/isolated\';iso.mkdir(exist_ok=True);shutil.copy2(root/\'model.py\',iso/\'model.py\')\\nres=subprocess.run([sys.executable,str(iso/\'model.py\')],cwd=root/\'sources\',capture_output=True,check=True)\\nraw=(root/\'model-output.json\').read_bytes();assert res.stdout==raw;assert not res.stderr\\n(root/\'verification/isolated-stdout.json\').write_bytes(res.stdout)\\nsha=lambda x:hashlib.sha256(x).hexdigest()\\nresult={\'single_file_stdlib\':True,\'different_cwd\':\'sources/\',\'stdout_exact_bytes_equal\':True,\'stdout_bytes\':len(raw),\'stdout_sha256\':sha(raw),\'isolated_stdout_sha256\':sha(res.stdout),\'model_sha256\':sha((root/\'model.py\').read_bytes()),\'production_tests\':a[\'tests\'],\'independent\':out,\'terminal_same_y5_state\':{},\'horizon_convergence\':{}}\\nbase=a[\'results\'][\'base\']\\nfor n in [\'holder_tail_low\',\'holder_tail_high\']:\\n r=a[\'results\'][n];assert r[\'first5_dps\']==base[\'first5_dps\'];assert r[\'rows\'][4][\'state\']==base[\'rows\'][4][\'state\'];result[\'terminal_same_y5_state\'][n]=True\\nfor n,r in a[\'results\'].items():\\n conv=r[\'horizon_pv\'];diff=conv[\'400\']-conv[\'200\'];assert abs(diff)<.001;result[\'horizon_convergence\'][n]={\'periods\':r[\'years\'],\'difference_200_to_400\':diff,\'all_annual_states_preserved\':True}\\n(root/\'verification/results.json\').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False,indent=2))\\n", \'verification/independent_literal.py\': "#!/usr/bin/env python3\\n# Independent literal recomputation. No import of production code, no reading inputs/output.\\n# Independent vector ordering: automobile, consumer, emerging, medical/security, analog/display, agency.\\nimport json\\n\\ndef recompute(gmchange=0,rdchange=0,growthchange=0,discount=.095):\\n    revenue=[6.6,6.,3.7,3.2,3.1,7.8]\\n    growth=[[.10,.12,.11,.10,.09],[.03,.07,.06,.05,.04],[.18,.18,.16,.14,.12],[.10,.10,.09,.08,.07],[.12,.12,.10,.09,.08],[.05,.04,.03,.03,.03]]\\n    margin=[.39,.32,.40,.39,.28,.08]\\n    pc,sc=3.52171122272,11.33749287941\\n    pd,sd=9.1756957764,4.26863783424\\n    pre,sre=.11670233358,8.;foreignre=6.8;domesticre=1.2\\n    pres,sres=.32831860261,1.\\n    capital=20.;p_capital=1.258151885;shares=1.24940168;loan=2.10806156831\\n    pf,sf=2.36482145047,4.78546042299;earmarked=3.1\\n    buybackdebt=0.\\n    investmentcost=23.29176180294;investmentbook=22.88285822232;futurefunding=0.\\n    pcapitalreserve=24.326714134;scapitalreserve=4.;ncibook=-.01938194004;ncicumulative=0.\\n    waiting=(.50085185,.50085185,0.)\\n    rows=[];pv=tv=0;pl=[];sl=[]\\n    for year in range(1,401):\\n        oldpc,oldsc,oldpd,oldsd=pc,sc,pd,sd\\n        revenue=[v*(1+(growth[i][year-1] if year<=5 else max(.02,growth[i][-1]-(year-5)*.012))+(growthchange if year<=10 else 0)) for i,v in enumerate(revenue)]\\n        design=sum(revenue[:5]);total=sum(revenue)\\n        fade=min(max(year-5,0)/15,1)\\n        gross=sum(v*(margin[i]+(gmchange-.02*fade if i<5 else 0)) for i,v in enumerate(revenue))\\n        ebit=gross-design*(.16+rdchange)-total*.04\\n        target=design*.68+revenue[5]*.32\\n        nextcapital=capital+(target-capital)/max(1,4-year) if year<=3 else target\\n        delta=nextcapital-capital;capital=nextcapital\\n        sn=ebit+sc*.018-sd*.035\\n        pn=-.12+pc*.018-pd*.035-(.0620381 if year==1 else 0)\\n        pl=[(t,x) for t,x in pl if year-t<=5];sl=[(t,x) for t,x in sl if year-t<=5]\\n        if pn<0:pl.append((year,-pn))\\n        if sn<0:sl.append((year,-sn))\\n        sn-=max(0,sn)*.20;pn-=max(0,pn)*.20\\n        sc+=sn-delta;pc+=pn\\n        # Literal service allocation: 250m annual noncash over five years, parent10%, subsidiary90%.\\n        if year<=5:\\n            sn-=.225;pn-=.025;investmentcost+=.225;investmentbook+=.225;pcapitalreserve+=.25;scapitalreserve+=.225\\n        if year==1:p_capital-=.008750205;pcapitalreserve-=.81339038565-.008750205\\n        if year==3:pcapitalreserve-=.375\\n        if year==1:pc+=.3375-.375;pd+=.3375;buybackdebt=.3375;shares-=.375/120\\n        if year==3:pc-=buybackdebt;pd-=buybackdebt;buybackdebt=0.;shares+=.375/120\\n        transfer=min(.62,earmarked);earmarked-=transfer;pc-=transfer;sc+=transfer\\n        fs=min(sf,4.78546042299/10) if year<=10 else 0\\n        fp=min(pf,2.36482145047/10) if year<=10 else 0\\n        sf-=fs;pf-=fp;sc+=fs*.9;pc+=fp*.9;sn-=fs*.1;pn-=fp*.1\\n        gross_paid,net_received,nci_paid=waiting;sc-=gross_paid;pc+=net_received\\n        floor=total*.12\\n        loanpaid=min(loan,.30,max(0,sc-floor));loan-=loanpaid;sc-=loanpaid;pc+=loanpaid\\n        srepay=min(sd,max(0,sc-floor)*.20);sd-=srepay;sc-=srepay\\n        prep=min(max(0,pd-buybackdebt),max(0,pc-.5-earmarked)*.20);pd-=prep;pc-=prep\\n        funding=max(0,floor-sc);fromp=min(max(0,pc-.5-earmarked),funding);pc-=fromp;sc+=fromp\\n        borrow=funding-fromp;sd+=borrow;sc+=borrow\\n        investmentcost+=transfer+fromp;investmentbook+=transfer+fromp;futurefunding+=transfer+fromp;scapitalreserve+=transfer+fromp\\n        foreignre+=sn*.85\\n        upstream=min(max(0,foreignre),max(0,sc-floor)*.85)\\n        foreignre-=upstream\\n        domesticincome=sn*.15+upstream\\n        radd=min(max(0,domesticre+domesticincome-max(domesticre,0))*.1,max(0,4.5-sres));domesticre+=domesticincome-radd;sres+=radd\\n        sre=foreignre+domesticre\\n        sr=[.55,.65,.75,.80,.85][year-1] if year<=5 else 1\\n        wanted=max(0,sn)*sr+max(0,sre-sn)*(.05 if year<=5 else .20)\\n        declare=max(0,min(max(domesticre,0),max(sc-floor,0),max(wanted,0)))\\n        domesticre-=declare;sre-=declare;net=declare*.995*.97;waiting=(declare,net,declare*.005)\\n        pn+=net\\n        ra=min(max(0,pre+pn-max(pre,0))*.1,max(0,p_capital*.5-pres));pre+=pn-ra;pres+=ra\\n        o23=.005887597 if year==1 else 0.;o25=.01498755/3 if year<=3 else 0.;opt=o23+o25\\n        gr=(.006/3 if year<=3 else 0)+(.010/5 if year<=5 else 0)\\n        p_capital+=opt+gr;shares+=opt+gr;pc+=o23*77.91+o25*138.57\\n        pcapitalreserve+=o23*77.91+o25*138.57-opt-gr\\n        ncibook+=sn*.005-declare*.005;ncicumulative+=nci_paid\\n        pr=[.35,.35,.40,.45,.50][year-1] if year<=5 else (.7 if year<=10 else 1)\\n        dividend=max(0,min(max(pre,0),max(pc-.5-earmarked,0),max(pre,0)*pr))\\n        pc-=dividend;pre-=dividend\\n        dps=dividend/shares;pv+=dps/(1+discount)**year\\n        if year>5:tv+=dps/(1+discount)**(year-5)\\n        rows.append({\'year\':year,\'dps\':dps,\'p_cash\':pc,\'s_cash\':sc,\'p_re\':pre,\'s_re\':sre,\'p_reserve\':pres,\'s_reserve\':sres,\'capital\':capital,\'p_debt\':pd,\'s_debt\':sd,\'loan\':loan,\'shares\':shares,\'declared\':declare,\'received\':net_received, \'foreign_local_re\':foreignre,\'domestic_local_re\':domesticre,\'p_capital\':p_capital,\'p_capital_reserve\':pcapitalreserve,\'s_capital\':9.,\'s_capital_reserve\':scapitalreserve,\'investment_cost\':investmentcost,\'investment_book\':investmentbook,\'future_funding\':futurefunding,\'p_earmark\':earmarked,\'p_financial\':pf,\'s_financial\':sf,\'nci_book\':ncibook,\'nci_cumulative\':ncicumulative,\'issued\':p_capital,\'treasury\':0.,\'treasury_cost\':(.375 if year<3 else 0.),\'new_treasury_cost\':(.375 if year<3 else 0.),\'buyback_new_treasury\':(.375/120 if year<3 else 0.),\'buyback_loan\':buybackdebt,\'pending_net\':net,\'pending_gross\':declare,\'receivable\':net,\'goodwill\':3.96329035235,\'p_tax_loss_carry\':sum(x for t,x in pl),\'s_tax_loss_carry\':sum(x for t,x in sl)})\\n    return {\'pv_per_share\':pv,\'terminal_year5\':tv,\'first5_dps\':[v[\'dps\'] for v in rows[:5]],\'rows\':rows}\\nresult={\'base\':recompute(),\'core_low\':recompute(-.006,.003,-.01,.10),\'rd_plus_1pct\':recompute(0,.01,0,.095)}\\nprint(json.dumps(result,ensure_ascii=False,sort_keys=True,indent=2))\\n", \'verification/long_horizon.py\': \'"""Independent invocation of production transition, full 800-year states preserved.\\nNot the independent literal verifier; its role is horizon truncation verification.\\n"""\\nimport pathlib,runpy,json,hashlib\\nroot=pathlib.Path(__file__).resolve().parents[1]\\nm=runpy.run_path(str(root/\\\'model.py\\\'))\\nold=json.loads((root/\\\'model-output.json\\\').read_text())[\\\'results\\\']\\nlong={};checks={}\\nfor name,before in old.items():\\n after=m[\\\'run\\\'](before[\\\'scenario_inputs\\\'],before[\\\'method\\\'],800)\\n # Matching entire state path including legal cash, loans, reserves, NCI and investment cost.\\n assert before[\\\'rows\\\']==after[\\\'rows\\\'][:len(before[\\\'rows\\\'])]\\n diff=after[\\\'pv_per_share\\\']-before[\\\'pv_per_share\\\'];assert abs(diff)<1e-7\\n long[name]=after\\n checks[name]={\\\'full_prefix_states_equal\\\':True,\\\'old_periods\\\':before[\\\'years\\\'],\\\'new_periods\\\':after[\\\'years\\\'],\\\'pv_400\\\':before[\\\'pv_per_share\\\'],\\\'pv_800\\\':after[\\\'pv_per_share\\\'],\\\'pv_difference\\\':diff,\\\'state_400\\\':before[\\\'rows\\\'][-1][\\\'state\\\'],\\\'state_800\\\':after[\\\'rows\\\'][-1][\\\'state\\\']}\\np=root/\\\'verification/long-horizon-output.json\\\';p.write_text(json.dumps(long,ensure_ascii=False,sort_keys=True,indent=2)+\\\'\\\\n\\\')\\nresult={\\\'method\\\':\\\'new 800-year invocation for every scenario; compare complete 400-year prefix and PV; full states retained in sibling JSON\\\',\\\'output_bytes\\\':p.stat().st_size,\\\'output_sha256\\\':hashlib.sha256(p.read_bytes()).hexdigest(),\\\'checks\\\':checks}\\n(root/\\\'verification/long-horizon-comparison.json\\\').write_text(json.dumps(result,ensure_ascii=False,indent=2)+\\\'\\\\n\\\')\\nprint(json.dumps({\\\'scenarios\\\':len(checks),\\\'all_passed\\\':True,\\\'bytes\\\':p.stat().st_size}))\\n# Tail-state verification, not merely repeated-prefix/PV checks.\\n# For terminal growth g, X_t = A*(1+g)^(t-400)+B after transients.\\n# Fit only 400/600; test 800 and EVERY year601..800 out-of-sample.\\naffine={}\\nfor name,v in long.items():\\n if v[\\\'years\\\']<800:\\n  row=v[\\\'rows\\\'][-1];e=row[\\\'exit\\\'];s=row[\\\'state\\\'];z=row[\\\'post_exit_state\\\']\\n  # Literal ledger rederivation from retained pre-exit state, not all-zero erasure.\\n  gross=s[\\\'capital\\\']*.65+s[\\\'s_cash\\\']+s[\\\'s_financial\\\']*.75\\n  senior=s[\\\'s_debt\\\']+.51554653691+.8\\n  avail=max(0,gross-senior);claims=s[\\\'loan\\\']+s[\\\'pending_gross\\\'];frac=min(1,avail/claims) if claims else 1\\n  remaining=max(0,avail-claims);nci=remaining*.005;eq=(remaining-nci)*.97\\n  tax=max(0,eq-s[\\\'investment_cost\\\'])*.25\\n  guarantee=min(s[\\\'s_debt\\\'],max(0,senior-gross))\\n  net=s[\\\'p_cash\\\']+eq-tax+s[\\\'loan\\\']*frac+s[\\\'pending_net\\\']*frac+s[\\\'p_financial\\\']*.75-s[\\\'p_debt\\\']-.15-guarantee\\n  income=eq-tax-s[\\\'investment_book\\\']-s[\\\'loan\\\']*(1-frac)-s[\\\'pending_net\\\']*(1-frac)-s[\\\'p_financial\\\']*.25-guarantee-.15\\n  assert abs(net-e[\\\'parent_liquidation_after_external_creditors\\\']+e[\\\'parent_creditor_shortfall\\\'])<1e-9\\n  assert abs(income-e[\\\'parent_realized_income\\\'])<1e-9\\n  assert z[\\\'parent_investment_cost_derecognized\\\']==s[\\\'investment_cost\\\']\\n  assert z[\\\'parent_creditor_shortfall\\\']==max(0,-net)\\n  assert z[\\\'sub_external_claims_unpaid_after_guarantee\\\']==max(0,senior-gross-e[\\\'parent_guarantee_cash_paid\\\'])\\n  affine[name]={\\\'type\\\':\\\'actual_liquidation_ledger\\\',\\\'cash_waterfall_recomputed\\\':True,\\\'income_and_historical_cost_recomputed\\\':True,\\\'pre_liquidation_state\\\':s,\\\'waterfall\\\':e,\\\'terminal_ledger\\\':z}\\n  continue\\n g=v[\\\'scenario_inputs\\\'].get(\\\'g\\\',.02);q=(1+g)**200;fields={};flows={}\\n for key in v[\\\'rows\\\'][399][\\\'state\\\']:\\n  a,b,c=[v[\\\'rows\\\'][i-1][\\\'state\\\'][key] for i in (400,600,800)]\\n  if key in [\\\'nci_cumulative\\\',\\\'future_funding\\\']:\\n   flows[key]={\\\'classification\\\':\\\'cumulative_historical_flow_not_a_stationary_stock\\\',\\\'values_400_600_800\\\':[a,b,c],\\\'increments_400_600_800\\\':[b-a,c-b]};continue\\n  A=(b-a)/(q-1);B=a-A\\n  predicted=A*q*q+B\\n  scale=max(1,abs(c),abs(predicted));error=abs(c-predicted)/scale\\n  all_errors=[abs(v[\\\'rows\\\'][t-1][\\\'state\\\'][key]-(A*(1+g)**(t-400)+B))/max(1,abs(v[\\\'rows\\\'][t-1][\\\'state\\\'][key]),abs(A*(1+g)**(t-400)+B)) for t in range(601,801)]\\n  maximum=max(all_errors);assert maximum<1e-8,(name,key,maximum)\\n  normalized=[(x-B)/(1+g)**(t-400) for x,t in zip([a,b,c],[400,600,800])]\\n  fields[key]={\\\'classification\\\':\\\'constant_or_zero_stock\\\' if abs(b-a)<1e-10 else \\\'affine_growth_stock\\\',\\\'values_400_600_800\\\':[a,b,c],\\\'terminal_growth\\\':g,\\\'fitted_growth_component_at400\\\':A,\\\'fixed_component\\\':B,\\\'growth_normalized_after_fixed_component\\\':normalized,\\\'predicted_800_from400_and600\\\':predicted,\\\'relative_residual_800\\\':error,\\\'maximum_relative_residual_years601_to800\\\':maximum,\\\'passed\\\':True}\\n affine[name]={\\\'type\\\':\\\'affine_terminal_state\\\',\\\'fit_years\\\':[400,600],\\\'test_years\\\':list(range(601,801)),\\\'tolerance_relative\\\':1e-8,\\\'stock_fields\\\':fields,\\\'cumulative_flows\\\':flows,\\\'all_state_fields_accounted_for\\\':len(fields)+len(flows)==len(v[\\\'rows\\\'][399][\\\'state\\\'])}\\n(root/\\\'verification/tail-state-convergence.json\\\').write_text(json.dumps(affine,ensure_ascii=False,sort_keys=True,indent=2)+\\\'\\\\n\\\')\\nprint(json.dumps({\\\'tail_state_paths\\\':len(affine),\\\'all_stock_fields_affine_test_passed\\\':True,\\\'exit_ledger_test_passed\\\':True}))\\n# Lossless archive when complete annual JSON exceeds 100 MiB; retain both raw and archive bytes/hashes.\\nif p.stat().st_size>100*1024*1024:\\n import lzma,shutil\\n archive=pathlib.Path(str(p)+\\\'.xz\\\');raw_bytes=p.stat().st_size;raw_sha=hashlib.sha256(p.read_bytes()).hexdigest()\\n with p.open(\\\'rb\\\') as source,lzma.open(archive,\\\'wb\\\',preset=6) as dest:shutil.copyfileobj(source,dest)\\n digest=hashlib.sha256();count=0\\n with lzma.open(archive,\\\'rb\\\') as f:\\n  while True:\\n   block=f.read(1024*1024)\\n   if not block:break\\n   count+=len(block);digest.update(block)\\n assert count==raw_bytes and digest.hexdigest()==raw_sha\\n compression={\\\'format\\\':\\\'xz lossless, complete UTF-8 JSON, no annual truncation\\\',\\\'raw_path\\\':str(p.relative_to(root)),\\\'raw_bytes\\\':raw_bytes,\\\'raw_sha256\\\':raw_sha,\\\'archive_path\\\':str(archive.relative_to(root)),\\\'archive_bytes\\\':archive.stat().st_size,\\\'archive_sha256\\\':hashlib.sha256(archive.read_bytes()).hexdigest(),\\\'decompressed_exact_bytes_and_sha256_verified\\\':True}\\n result[\\\'compression\\\']=compression\\n (root/\\\'verification/long-horizon-comparison.json\\\').write_text(json.dumps(result,ensure_ascii=False,indent=2)+\\\'\\\\n\\\')\\n (root/\\\'verification/archive-verification.json\\\').write_text(json.dumps(compression,ensure_ascii=False,indent=2)+\\\'\\\\n\\\')\\n p.unlink()\\n print(json.dumps(compression))\\n\'}\nwith tempfile.TemporaryDirectory(prefix=\'omni-full-verifier-\') as temp:\n    r=Path(temp);(r/\'sources\').mkdir();(r/\'verification\').mkdir()\n    for name,value in _FILES.items():(r/name).write_text(value)\n    shutil.copyfile(here/\'2026-Q3.py\',r/\'model.py\')\n    shutil.copyfile(here/\'2026-Q3-output.json\',r/\'model-output.json\')\n    literal=subprocess.check_output([sys.executable,\'-I\',\'-S\',str(r/\'verification/independent_literal.py\')],cwd=r/\'sources\')\n    (r/\'verification/independent-output.json\').write_bytes(literal)\n    assert hashlib.sha256(literal).hexdigest()==\'b928e8dd6e765d8a03a27dfbdaf8e29a554d501e789617d4e453080687aaad0a\'\n    for script in [\'verify.py\',\'long_horizon.py\']:subprocess.run([sys.executable,str(r/\'verification\'/script)],cwd=r/\'sources\',check=True)\n    raw=lzma.decompress((r/\'verification/long-horizon-output.json.xz\').read_bytes())\n    assert len(raw)==113228106 and hashlib.sha256(raw).hexdigest()==\'de1b691954556033e65165c5357848fe0c31f74e8dcdfa32440a1d1afb0dd228\'\n    exec(compile("with contextlib.redirect_stdout(io.StringIO()):ind=runpy.run_path(str(r/\'verification/independent_literal.py\'))\\nhigh=ind[\'recompute\'](.006,-.003,.01,.09);prod=json.loads((r/\'model-output.json\').read_text())[\'results\'][\'core_high\'];errors=[]\\nfor x,y in zip(prod[\'rows\'],high[\'rows\']):\\n for k,z in y.items():\\n  if k==\'year\':continue\\n  pv=x[\'holder_dps\']if k==\'dps\' else x[\'sub_gross_declared\']if k==\'declared\' else x[\'received_prior_dividends\']if k==\'received\' else x[\'state\'][k]\\n  errors.append(abs(pv-z));assert abs(pv-z)<1e-7,(k,x[\'year\'],pv,z)\\nassert abs(prod[\'pv_per_share\']-high[\'pv_per_share\'])<1e-9\\n\\nprint(json.dumps({\'independent_core_high_fields\':len(errors),\'maximum_error\':max(errors),\'all_passed\':True}))\\n",__file__,\'exec\'),{\'r\':r,\'contextlib\':contextlib,\'io\':io,\'runpy\':runpy,\'json\':json})\n\nexec(compile("import pathlib,json,sys,decimal,importlib.util\\nfrom decimal import Decimal as D\\nr=pathlib.Path(__file__).resolve().parent;a=json.loads((r/\'2026-Q3-output.json\').read_text())\\ndef eq(x,y):assert abs(x-y)<1e-8+1e-10*max(abs(x),abs(y)),(x,y)\\n# Different literal arithmetic for first-year demand/gross profit/R&D and cash taxes.\\nrev=[D(x)*(1+D(g))for x,g in zip([\'6.6\',\'6\',\'3.7\',\'3.2\',\'3.1\',\'7.8\'],[\'.10\',\'.03\',\'.18\',\'.10\',\'.12\',\'.05\'])]\\nebit=sum(v*D(m)for v,m in zip(rev,[\'.39\',\'.32\',\'.40\',\'.39\',\'.28\',\'.08\']))-sum(rev[:-1])*D(\'.16\')-sum(rev)*D(\'.04\')\\nrow=a[\'results\'][\'base\'][\'rows\'][0];eq(row[\'ebit\'],float(ebit))\\nsp=ebit+D(\'11.33749287941\')*D(\'.018\')-D(\'4.26863783424\')*D(\'.035\')\\npp=-D(\'.12\')+D(\'3.52171122272\')*D(\'.018\')-D(\'9.1756957764\')*D(\'.035\')-D(\'.0620381\')\\neq(row[\'sub_cash_tax\'],float(max(0,sp)*D(\'.2\')));eq(row[\'parent_cash_tax\'],float(max(0,pp)*D(\'.2\')))\\ncount=0\\nfor name,v in a[\'results\'].items():\\n b=dict(a[\'inputs\'][\'opening\']);b[\'shares\']=b[\'issued\']-b[\'treasury\'];b[\'nci_cumulative\']=0;b[\'future_funding\']=0\\n # First-year actual beginning variants are evaluated separately by formal production fixtures;\\n # audit all subsequent adjacent records independently to avoid inventing scenario initialization.\\n for row in v[\'rows\']:\\n  c=row[\'state\'];y=row[\'year\'];count+=1\\n  assert row[\'sub_cash_tax\']>=0 and row[\'parent_cash_tax\']>=0\\n  eq(c[\'shares\'],c[\'issued\']-c[\'treasury\']-c[\'buyback_new_treasury\'])\\n  eq(c[\'s_re\'],c[\'foreign_local_re\']+c[\'domestic_local_re\'])\\n  assert c[\'s_cash\']+1e-8>=c[\'pending_gross\']\\n  if y>1:\\n   paidgross=b[\'pending_gross\']+row[\'sub_gross_declared\']-c[\'pending_gross\']\\n   div=row[\'holder_cash\']-(row.get(\'exit\',{}).get(\'parent_liquidation_after_external_creditors\',0))\\n   expected=row[\'sub_net_income\']+row[\'parent_own_income\']+row[\'noncash_share_compensation\']+row[\'financial_book_sold\']+row.get(\'parent_emergency_financial_book_sold\',0)-row[\'net_capital_investment\']-(paidgross-row[\'received_prior_dividends\'])-row[\'parent_debt_paid\']-row[\'sub_debt_paid\']-row.get(\'bond_cash_principal_without_refinancing\',0)+row[\'new_external_borrowing\']+row[\'option_exercise_cash\']-div+row[\'buyback_loan_draw\']-row[\'planned_buyback_cash\']-row[\'buyback_loan_repaid\']\\n   eq(c[\'p_cash\']+c[\'s_cash\']-b[\'p_cash\']-b[\'s_cash\'],expected)\\n   eq(c[\'p_re\'],b[\'p_re\']+row[\'parent_own_income\']+row[\'parent_recognized_new_dividend_income\']-row[\'parent_reserve_added\']-div)\\n   eq(c[\'s_re\'],b[\'s_re\']+row[\'sub_net_income\']-row[\'sub_reserve_added\']-row[\'sub_gross_declared\'])\\n   eq(c[\'investment_cost\'],b[\'investment_cost\']+row[\'parent_new_investment\']+row[\'parent_noncash_investment_cost_added\'])\\n   eq(c[\'loan\'],b[\'loan\']-row[\'loan_principal_paid\']-row.get(\'accelerated_intercompany_principal_recovered\',0))\\n   eq(c[\'nci_book\'],b[\'nci_book\']+row[\'sub_net_income\']*.005-row[\'nci_declared\'])\\n   eq(c[\'p_debt\']+c[\'s_debt\'],b[\'p_debt\']+b[\'s_debt\']+row[\'buyback_loan_draw\']-row[\'buyback_loan_repaid\']+row[\'new_external_borrowing\']-row[\'parent_debt_paid\']-row[\'sub_debt_paid\']-row.get(\'bond_cash_principal_without_refinancing\',0))\\n  b=c\\nspec=importlib.util.spec_from_file_location(\'m\',r/\'2026-Q3.py\');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)\\nassert m.statutory(-3,.2,10,2)==(-1,.2,0)\\nassert m.payment(-1,10,0,10)==0 and m.payment(5,2,1,5)==1\\nloss=m.run({\'gm_shift\':-.25},years=2)\\nassert all(x[\'sub_cash_tax\']==0 and x[\'sub_tax_pretax\']<0 for x in loss[\'rows\'])\\n# Refusal gates are re-executed against the actual production transition.\\nrefused=m.run({\'bond_refused\':True},years=2);rr=refused[\'rows\'][0]\\neq(rr[\'bond_cash_redemption\'],2.6755553);assert rr[\'bond_refinancing_bank_proceeds\']==0 and rr[\'bond_due_unpaid_after_parent_asset_sale_and_loan_recovery\']==0\\nassert rr[\'parent_emergency_financial_book_sold\']<=2.36482145047 and rr[\'accelerated_intercompany_principal_recovered\']==0\\nshort=m.run({\'bond_refused\':True,\'financial_recovery\':.5,\'no_loan_acceleration\':True},years=5)\\nassert short[\'years\']==1 and short[\'rows\'][0][\'funding_triggered_exit\']\\nassert short[\'rows\'][0][\'shares_exercised\']==0 and short[\'rows\'][0][\'shares_awarded\']==0\\nassert short[\'rows\'][0][\'bond_due_unpaid_after_parent_asset_sale_and_loan_recovery\']>0\\nprint(json.dumps({\'passed\':True,\'annual_rows\':count,\'paths\':len(a[\'results\']),\'independent_Decimal_Y1_EBIT\':str(ebit),\'parent_Y1_taxable_income\':str(pp),\'parent_cash_tax\':str(max(0,pp)*D(\'.2\')),\'scope\':\'cash, dividend recognition, investment cost, loan/NCI, tax loss and legal payment; separate full literal and long-tail audit required\'},indent=2))\\n",__file__,"exec"),{"__file__":__file__,"__name__":"__main__"})\n'
with tempfile.TemporaryDirectory(prefix='q3-lossless-full-')as tmp:
    target=Path(tmp);source=here/'2026-Q3-output.json';raw=target/'2026-Q3-output.json'
    assert source.is_file() and not source.is_symlink()
    if source.stat().st_size<=4096:
        meta=json.loads(source.read_text());assert meta==expected
        assert meta['schema']=='trading_os_lossless_json_xz_v1' and meta['artifact_kind']=='transport_manifest_not_model_result'
        assert meta['compression']=='xz' and meta['file']=='2026-Q3-output.json.xz' and meta['expanded_media_type']=='application/json'
        assert 0<meta['compressed_bytes']<=100*1024**2 and 0<meta['expanded_bytes']<=512*1024**2
        zipped=here/meta['file'];assert zipped.is_file() and not zipped.is_symlink() and zipped.resolve().parent==here.resolve()
        assert zipped.stat().st_size==meta['compressed_bytes']
        with zipped.open('rb')as f:assert hashlib.file_digest(f,'sha256').hexdigest()==meta['compressed_sha256']
        dec=lzma.LZMADecompressor(format=lzma.FORMAT_XZ,memlimit=256*1024**2);total=0
        with zipped.open('rb')as inp,raw.open('wb')as out:
            while chunk:=inp.read(65536):
                assert not dec.eof
                block=dec.decompress(chunk,max_length=1048576)
                while True:
                    total+=len(block);assert total<=meta['expanded_bytes'];out.write(block)
                    if dec.eof or dec.needs_input:break
                    block=dec.decompress(b'',max_length=1048576)
            assert dec.eof and not dec.unused_data and total==meta['expanded_bytes']
    else:shutil.copyfile(source,raw)
    assert raw.stat().st_size==expected['expanded_bytes']
    with raw.open('rb')as f:assert hashlib.file_digest(f,'sha256').hexdigest()==expected['expanded_sha256']
    model=here/'2026-Q3.py';assert model.is_file() and not model.is_symlink();shutil.copyfile(model,target/'2026-Q3.py')
    checker=target/'2026-Q3-independent-recompute.py';checker.write_text(original_checker)
    subprocess.run([sys.executable,'-I','-S',str(checker)],cwd=target,check=True)
